// Carpeta de los dibujos, copiados de la app por el generador.
const CAT_DIBUJOS = 'media/ejercicios/';

/* Ruta del dibujo de un ejercicio, o null si no tiene (los personalizados del
   entrenador nunca tienen). Quien la pinte debe reservar el hueco en vez de
   dejar un rectángulo vacío. El nombre lleva espacios y acentos, así que va
   codificado. */
function imagenEjercicio(nombre){
  const f = CAT_FICHA[nombre];
  return f && f.img ? CAT_DIBUJOS + encodeURIComponent(f.img) + '.webp' : null;
}

/** Ficha de un ejercicio de la biblioteca, o null si no es de la biblioteca. */
function fichaEjercicio(nombre){
  return CAT_FICHA[nombre] || null;
}

// Grupo muscular de cada ejercicio (derivado de la ficha).
const CAT_GRUPO_DE = Object.fromEntries(
  Object.entries(CAT_FICHA).map(([nombre, f]) => [nombre, f.grupo]));

